style.css:
html,
body {
    background: transparent !important;
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    background-image: url("https://i.imgur.com/8z5sCG4.jpeg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    z-index: -9999;
    pointer-events: none;
}
